import os,re,sys
def res(path, svc, env, host, over, out):
    for l in open(over.get(os.path.abspath(path), path)):
        l=l.strip()
        yield_ = None
    sec=None
    for l in open(over.get(os.path.abspath(path), path)):
        l=l.strip()
        if not l or l.startswith('#'): continue
        m=re.match(r'\[(.*)\]$',l)
        if m: sec=m.group(1); continue
        k,_,v=[x.strip() for x in l.partition('=')]
        if k=='include':
            if sec is None:
                p=os.path.normpath(os.path.join(os.path.dirname(path),v.replace('${env}',env).replace('${host}',host)))
                res(p,svc,env,host,over,out)
            continue
        if sec is None or sec==svc: out.append((k,v,path,sec))
svc=sys.argv[1]
over={os.path.abspath('config/profiles/edge.conf'):'config-history/r0418/prev/profiles/edge.conf'}
out=[];res('services/%s/service.conf'%svc,svc,'prod-b','app-07',over,out)
d={}
for k,v,p,s in out:
    if k in('port_base','port_offset','admin_port'): print(k,v,p,s)
